// Demo catalog: a UK service, prices in pounds. Single source of truth for local development, unit
// tests and supabase/seed.sql (generated by `npm run db:seed`). Fully deterministic: no random values.

import type { AvailabilityException, AvailabilityRule } from "../booking/types";
import type { Category, Provider, Review, Service } from "./types";

const uuid = (prefix: string, n: number) =>
  `00000000-0000-4000-${prefix}-${n.toString().padStart(12, "0")}`;

/** Every city in the catalog is in Great Britain or Northern Ireland: one time zone. */
const TIMEZONE = "Europe/London";
const CURRENCY = "GBP";

/** Weekly hours in local provider time. Picked per provider to match how the job is done. */
const SCHEDULES = {
  // Office hours with a lunch break. Tests rely on Anna's 09:00–13:00, 14:00–18:00 days.
  office: {
    days: [1, 2, 3, 4, 5],
    hours: [
      ["09:00", "13:00"],
      ["14:00", "18:00"],
    ],
  },
  // Before and after work, plus Saturday morning: personal trainers.
  trainer: {
    days: [1, 2, 3, 4, 5],
    hours: [
      ["06:30", "10:00"],
      ["17:00", "20:30"],
    ],
    saturday: ["08:00", "12:00"],
  },
  // After school on weekdays and Saturday mornings: tutors and music teachers.
  afterSchool: {
    days: [1, 2, 3, 4],
    hours: [["15:30", "20:00"]],
    saturday: ["09:00", "13:00"],
  },
  // A studio open Tuesday to Saturday: massage therapists and teachers with a space.
  studio: { days: [2, 3, 4, 5, 6], hours: [["10:00", "18:00"]] },
  // Mornings and evenings around a day job: online teachers and coaches.
  split: {
    days: [1, 3, 4],
    hours: [
      ["07:30", "09:30"],
      ["18:00", "21:00"],
    ],
    saturday: ["10:00", "14:00"],
  },
  // Coaches with a few long days.
  coaching: { days: [1, 2, 4], hours: [["08:30", "17:30"]] },
} satisfies Record<string, { days: number[]; hours: string[][]; saturday?: string[] }>;

type ServiceInput = {
  title: string;
  description: string;
  durationMin: number;
  /** Whole pounds; 0 is a free intro. Stored in integer pence. */
  price: number;
  /** A service the provider has switched off: hidden from the catalog, kept for old bookings. */
  inactive?: true;
};

type ProviderInput = {
  name: string;
  category: Category;
  city: string;
  formats: "online" | "in_person" | "both";
  headline: string;
  bio: string;
  years: number;
  languages: string[];
  services: ServiceInput[];
  schedule: keyof typeof SCHEDULES;
  /** How many reviews the profile has. New providers have few or none. */
  reviews: number;
  status?: Provider["status"];
};

const s = (
  title: string,
  durationMin: number,
  price: number,
  description: string,
  inactive?: true,
): ServiceInput => ({ title, durationMin, price, description, inactive });

