/** Reviews with a "but": they get 3 or 4 stars, never 5, so the stars match the words. */
const MIXED_REVIEWS = new Set([
  "Good lessons, though a bit fast at first. Slowed down when I asked.",
  "Good coach. The early slots are popular, so book ahead.",
  "Great teacher, though it took a few sessions to find the right pace.",
  "Good sessions. I would have liked a bit more follow-up between them.",
  "Lovely massage, though the room was a little cold.",
  "Good teacher. Online lessons had a few sound issues at first.",
]);

/**
 * Stars for one review. Every fourth provider gets only fives, the rest a four every 2nd, 3rd or
 * 4th review: averages from about 4.5 to 5.0 instead of the same 4.6 everywhere.
 */
function ratingFor(body: string, providerIndex: number, k: number): number {
  if (MIXED_REVIEWS.has(body)) return (providerIndex + k) % 3 === 0 ? 3 : 4;
  const every = providerIndex % 4; // 0: never a four
  return every > 0 && k % (every + 1) === every ? 4 : 5;
}

// Demo photos (Unsplash License) stored in public/images/providers. Everyone else gets initials.
const PHOTOS = new Set(["anna-yoga", "marcus-fitness", "emma-coaching"]);

const slugify = (name: string, category: Category) =>
  `${name.split(" ")[0]}-${category}`.toLowerCase().replace(/[^a-z0-9-]/g, "");

export const providers: Provider[] = PROVIDERS.map((p, i) => ({
  id: uuid("8000", i + 1),
  slug: slugify(p.name, p.category),
  photoUrl: PHOTOS.has(slugify(p.name, p.category))
    ? `/images/providers/${slugify(p.name, p.category)}.jpg`
    : null,
  displayName: p.name,
  headline: p.headline,
  bio: p.bio,
  category: p.category,
  city: p.city,
  timezone: TIMEZONE,
  offersOnline: p.formats !== "in_person",
  offersInPerson: p.formats !== "online",
  yearsExperience: p.years,
  languages: p.languages,
  status: p.status ?? "approved",
  updatedAt: `2026-10-${String((i % 15) + 1).padStart(2, "0")}T09:00:00.000Z`,
}));

let serviceCounter = 0;
export const services: Service[] = PROVIDERS.flatMap((p, i) =>
  p.services.map((t) => ({
    id: uuid("9000", ++serviceCounter),
    providerId: uuid("8000", i + 1),
    title: t.title,
    description: t.description,
    durationMin: t.durationMin,
    // Money is stored in integer minor units (pence).
    priceCents: t.price * 100,
    currency: CURRENCY,
    active: !t.inactive,
  })),
);

const DAY_MS = 24 * 60 * 60 * 1000;
const FIRST_REVIEW = Date.UTC(2025, 10, 3, 12); // 3 November 2025

let reviewCounter = 0;
export const reviews: Review[] = PROVIDERS.flatMap((p, i) =>
  Array.from({ length: p.reviews }, (_, k) => {
    const n = ++reviewCounter;
    const bodies = REVIEW_BODIES[p.category];
    const body = bodies[(i * 3 + k) % bodies.length]!;
    return {
      id: uuid("a000", n),
      providerId: uuid("8000", i + 1),
      authorName: REVIEW_AUTHORS[(i * 5 + k * 7) % REVIEW_AUTHORS.length]!,
      rating: ratingFor(body, i, k),
      body,
      // Spread over the last year, up to late October 2026.
      createdAt: new Date(FIRST_REVIEW + ((n * 41 + i * 13) % 355) * DAY_MS).toISOString(),
      // One hidden review shows that moderation-hidden content never reaches the page.
      hidden: n === 5,
    };
  }),
);

let ruleCounter = 0;
export const availabilityRules: AvailabilityRule[] = PROVIDERS.flatMap((p, i) => {
  const schedule: { days: number[]; hours: string[][]; saturday?: string[] } =
    SCHEDULES[p.schedule];
  const weekly = schedule.days.flatMap((weekday) =>
    schedule.hours.map(([startTime, endTime]) => ({ weekday, startTime, endTime })),
  );
  if (schedule.saturday) {
    weekly.push({ weekday: 6, startTime: schedule.saturday[0], endTime: schedule.saturday[1] });
  }
  return weekly.map((r) => ({
    id: uuid("b000", ++ruleCounter),
    providerId: uuid("8000", i + 1),
    weekday: r.weekday,
    startTime: r.startTime!,
    endTime: r.endTime!,
  }));
});

const indexOf = (name: string) => {
  const i = PROVIDERS.findIndex((p) => p.name === name);
  if (i < 0) throw new Error(`Unknown seed provider: ${name}`);
  return i;
};

